- name: Slack notify on failure
  if: failure()
  uses: slackapi/slack-github-action@v1
  with:
    payload: |
      {
        "text": "CI failed: ${{ github.workflow }} on ${{ github.ref_name }}",
        "blocks": [{
          "type": "section",
          "text": { "type": "mrkdwn", "text": "*${{ github.workflow }}* failed on `${{ github.ref_name }}` by ${{ github.actor }}\n<${{ github.server_url }}/${{ github.repository }}/actions/runs/${{ github.run_id }}|View run>" }
        }]
      }
  env:
    SLACK_WEBHOOK_URL: ${{ secrets.SLACK_WEBHOOK_URL }}
